#!/usr/bin/env node
/**
 * Live verification harness for the Transcript Forge.
 *
 * Usage:  node scripts/verify-transcript-forge.mjs [baseUrl]
 *         BASE_URL=http://localhost:3111 node scripts/verify-transcript-forge.mjs
 *
 * Matrix covers: manual captions, auto-generated captions, caption-less
 * (ASR escalation path), and a cache re-hit. Results are reported per case;
 * only the core contract is asserted.
 */

const BASE_URL = process.argv[2] || process.env.BASE_URL || "http://localhost:3111";

const CASES = [
    { id: "dQw4w9WgXcQ", label: "manual captions expected" },
    { id: "aqz-KE-bpKQ", label: "animated short, mixed captions" },
    { id: "jNQXAC9IVRw", label: "19s legacy upload" },
    { id: "TI6kOOvjtYI", label: "small-channel video (ASR escalation likely)" },
];

async function hit(path) {
    const started = Date.now();
    try {
        const res = await fetch(`${BASE_URL}${path}`);
        const body = await res.json().catch(() => ({}));
        return { status: res.status, body, ms: Date.now() - started };
    } catch (error) {
        return { status: 0, body: { error: String(error) }, ms: Date.now() - started };
    }
}

async function main() {
    console.log(`\n🧪 Transcript Forge verification → ${BASE_URL}\n`);

    const status = await hit("/api/get-transcript/status");
    if (status.status === 200) {
        for (const p of status.body.providers ?? []) {
            console.log(`   provider ${p.name.padEnd(10)} available=${p.available}`);
        }
    } else {
        console.log(`   ⚠️ status endpoint unreachable (${status.status})`);
    }
    console.log("");

    let failures = 0;

    // Cache warm pass + immediate re-hit to prove persistence.
    const first = await hit(`/api/get-transcript?videoId=dQw4w9WgXcQ`);
    const second = await hit(`/api/get-transcript?videoId=dQw4w9WgXcQ`);
    const cachedOk =
        first.status === 200 &&
        second.status === 200 &&
        typeof first.body.wordCount === "number";

    if (!cachedOk) {
        failures++;
        console.log("❌ CORE: baseline fetch/cache cycle failed");
        console.log(`   first=${first.status} ${JSON.stringify(first.body).slice(0, 200)}`);
        console.log(`   second=${second.status} ${JSON.stringify(second.body).slice(0, 200)}`);
    } else {
        console.log(
            `✅ CORE: dQw4w9WgXcQ ok — ${first.body.wordCount} words via "${first.body.source}" (${first.ms}ms), ` +
                `re-hit ${second.ms}ms cached=${String(second.body.source).includes("cached")}`
        );
        console.log(
            `   meta: lang=${first.body.language} auto=${first.body.isAutoGenerated} asr=${first.body.asr}`
        );
    }

    for (const testCase of CASES.slice(1)) {
        const result = await hit(`/api/get-transcript?videoId=${testCase.id}`);
        if (result.status === 200 && result.body.wordCount > 0) {
            console.log(
                `✅ ${testCase.id} (${testCase.label}) — ${result.body.wordCount} words via "${result.body.source}" in ${result.ms}ms`
            );
        } else if (result.status === 404 && result.body.verifiedCaptionless) {
            console.log(`⚠️  ${testCase.id} (${testCase.label}) — verified caption-less, ASR could not produce text`);
            console.log(`    attempts: ${(result.body.attempts ?? []).join(" | ")}`);
        } else {
            failures++;
            console.log(`❌ ${testCase.id} (${testCase.label}) — HTTP ${result.status}`);
            console.log(`    ${JSON.stringify(result.body).slice(0, 300)}`);
        }
    }

    const bad = await hit("/api/get-transcript?videoId=short");
    if (bad.status === 400) {
        console.log("✅ INPUT VALIDATION: invalid id rejected with 400");
    } else {
        failures++;
        console.log(`❌ INPUT VALIDATION: expected 400, got ${bad.status}`);
    }

    console.log(failures === 0 ? "\n🎉 All checks passed\n" : `\n💥 ${failures} check(s) failed\n`);
    process.exit(failures === 0 ? 0 : 1);
}

main();
